{
  "cases": [
    {
      "id": "AI-12345",
      "title": "Synthetic Healthcare Workflow Case: Multiple Submissions, Readbacks, and Transitions",
      "rule_ids": ["WF-001","WF-002","WF-003","WF-004","WF-005"],
      "rationale": "This case tests the workflow's ability to handle multiple submissions, readbacks, and transitions, including duplicate submissions, unauthorized reads, and invalid transitions.",
      "assumptions": [],
      "steps": [
        {
          "action": "submit",
          "actor": "customer-m100",
          "data": {"claim_id":"SURV-561","member_id":"M100","service":"medical","amount_cents":112345},
          "expect": {
            "status": 201,
            "claim_status": "submitted",
            "revision": 1,
            "payout_cents": 102345,
            "event_count": 1,
            "payment_cents": null
          }
        },
        {
          "action": "read",
          "actor": "customer-m200",
          "data": {"claim_id":"SURV-561"},
          "expect": {
            "status": 403,
            "error": "FORBIDDEN"
          }
        },
        {
          "action": "submit",
          "actor": "customer-m100",
          "data": {"claim_id":"SURV-561","member_id":"M100","service":"medical","amount_cents":112345},
          "expect": {
            "status": 409,
            "error": "DUPLICATE_CLAIM"
          }
        },
        {
          "action": "read",
          "actor": "customer-m100",
          "data": {"claim_id":"SURV-561"},
          "expect": {
            "status": 200,
            "claim_status": "submitted",
            "revision": 1,
            "payout_cents": 102345,
            "event_count": 1,
            "payment_cents": null
          }
        },
        {
          "action": "transition",
          "actor": "finance-demo",
          "data": {"claim_id":"SURV-561","target":"paid"},
          "expect": {
            "status": 409,
            "error": "INVALID_TRANSITION"
          }
        },
        {
          "action": "read",
          "actor": "customer-m100",
          "data": {"claim_id":"SURV-561"},
          "expect": {
            "status": 200,
            "claim_status": "submitted",
            "revision": 1,
            "payout_cents": 102345,
            "event_count": 1,
            "payment_cents": null
          }
        },
        {
          "action": "transition",
          "actor": "adjuster-demo",
          "data": {"claim_id":"SURV-561","target":"approved"},
          "expect": {
            "status": 200,
            "claim_status": "approved",
            "revision": 2,
            "payout_cents": 102345,
            "event_count": 2,
            "payment_cents": null
          }
        },
        {
          "action": "transition",
          "actor": "finance-demo",
          "data": {"claim_id":"SURV-561","target":"paid"},
          "expect": {
            "status": 200,
            "claim_status": "paid",
            "revision": 3,
            "payout_cents": 102345,
            "event_count": 3,
            "payment_cents": 102345
          }
        }
      ]
    }
  ]
}

